        filters.push(`名称包含「${value.name_contains.trim()}」`);
    const types = list(value.card_type);
    if (types.length)
        filters.push(types.map(type => typeNames[type] || type).join('/'));
    const rarities = list(value.rarity);
    if (rarities.length)
        filters.push(rarities.map(rarity => rarityNames[rarity] || rarity).join('/'));
    if (value.cost !== undefined)
        filters.push(`${formula(value.cost, options)}费`);
    if (value.min_cost !== undefined)
        filters.push(`至少${formula(value.min_cost, options)}费`);
    if (value.max_cost !== undefined)
        filters.push(`至多${formula(value.max_cost, options)}费`);
    const tags = list(value.tag);
    if (tags.length)
        filters.push(`标签:${tags.join('+')}`);
    const template = value.template_id ?? value.id;
    if (template !== undefined)
        filters.push(options.cardNames?.[String(template)] ? `卡牌:${options.cardNames[String(template)]}` : '指定卡牌');
    if (value.run_instance_id !== undefined)
        filters.push('指定整局实例');
    if (value.combat_instance_id !== undefined)
        filters.push('指定战斗实例');
    if (value.origin !== undefined)
        filters.push(`来源:${{ deck: '初始牌组', generated: '生成', copied: '复制', transformed: '变形' }[String(value.origin)] || '指定来源'}`);
    if (value.upgraded !== undefined)
        filters.push(value.upgraded ? '已升级' : '未升级');
    const keywordNames = {
        retain: '保留', exhaust: '消耗', ethereal: '虚无', innate: '固有', sly: '灵巧',
    };
    const keywords = list(value.keyword);
    if (keywords.length)
        filters.push(keywords.map(keyword => keywordNames[keyword] || keyword).join('+'));
    const excludedKeywords = list(value.exclude_keyword);
    if (excludedKeywords.length) {
        filters.push(`不含${excludedKeywords.map(keyword => keywordNames[keyword] || keyword).join('+')}`);
    }
    if (value.root_only !== undefined)
        filters.push(value.root_only ? '仅谱系原卡' : '包含临时副本');
