        ...node.optionalFeatures.flatMap(predicate => (predicate.values || []).map(value => `${predicate.field}:${value}`)),
        ...node.payoffFeatures.flatMap(predicate => (predicate.values || []).map(value => `${predicate.field}:${value}`)),
