        const assertCurrent = () => {
            if (destroyed || mvuMonitor.getSnapshot().chatId !== chatId
                || host.getLastMessageId() !== latestMessageId
                || host.getChatMessages?.(messageId)?.at(-1)?.swipe_id !== swipeId)
                throw new Error('聊天、楼层或回复已变化，已取消旧页面保存');
        };
